// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 deposit) public {
        deposit = bound(deposit, 1, 1 ether);
        vm.assume(caller != address(0));

        vm.deal(caller, deposit);

        vm.prank(caller);
        (bool sent,) = address(c).call{value: deposit}("\x00");
        require(sent);

        uint256 balBefore = address(c).balance;
        require(balBefore == deposit);

        vm.prank(caller);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        bool callerIsOwner = (caller == address(this));

        uint256 balAfter = address(c).balance;

        assertTrue(callerIsOwner || balAfter == balBefore);
    }
}
